//! The TypeScript backend (spec chapter 8).
//!
//! It reads only the IR. Each module becomes a file under `src/` (std modules under `src/std/`,
//! examples under `examples/`), built as a TypeScript tree and then printed. The runtime
//! `src/wolf_rt.ts` holds only the pieces the program uses.

mod emit;
mod names;
mod runtime;
mod ts;

use std::collections::BTreeSet;

use wolf_ir::{ModuleRole, Program, ProgramKind};

/// A generated file, with its path relative to `out/ts/`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OutFile {
    /// The path, with `/` separators.
    pub path: String,
    /// The contents.
    pub contents: String,
}

/// Generates the TypeScript project for a program; with `tests`, a test build that also contains
/// the tests and `*.test.ts` files for `node:test`. An error names a construct the backend does
/// not support yet; the driver reports it as an internal compiler error.
pub fn generate(
    program: &Program,
    wolf_version: &str,
    tests: bool,
) -> Result<Vec<OutFile>, String> {
    let mut e = emit::Emitter::new(program, tests);
    let mut files: Vec<OutFile> = Vec::new();
    let put = |files: &mut Vec<OutFile>, (path, contents): (String, String)| match files
        .iter_mut()
        .find(|f| f.path == path)
    {
        Some(f) => f.contents = contents,
        None => files.push(OutFile { path, contents }),
    };
    for (i, m) in program.modules.iter().enumerate() {
        let wanted = match m.role {
            ModuleRole::Entry | ModuleRole::Src => true,
            ModuleRole::Example => !tests,
            ModuleRole::Test => tests,
            ModuleRole::Std => false,
        };
        if wanted {
            if let Some(f) = e.module(i)? {
                put(&mut files, f);
            }
        }
    }
    // Std modules that the program refers to, until no new ones are needed.
    let mut emitted: BTreeSet<usize> = BTreeSet::new();
    loop {
        let pending: Vec<usize> = e.wanted.difference(&emitted).copied().collect();
        if pending.is_empty() {
            break;
        }
        for i in pending {
            emitted.insert(i);
            if let Some(f) = e.module(i)? {
                put(&mut files, f);
            }
        }
    }
    // Re-emit std modules once more so that snippets requested later are included.
    for i in emitted.clone() {
        if let Some(f) = e.module(i)? {
            put(&mut files, f);
        }
    }
    for (path, contents) in std::mem::take(&mut e.test_files) {
        files.push(OutFile { path, contents });
    }
    if tests {
        files.push(OutFile {
            path: "src/node_test.d.ts".to_string(),
            contents: NODE_TEST.to_string(),
        });
        files.push(OutFile {
            path: "wolf_test_reporter.mjs".to_string(),
            contents: format!("// Generated by wolf {wolf_version}. Do not edit.\n{REPORTER}"),
        });
    }
    files.push(OutFile {
        path: "src/wolf_rt.ts".to_string(),
        contents: emit::runtime_file(&e.rt, wolf_version),
    });
    files.push(OutFile {
        path: "package.json".to_string(),
        contents: package_json(program),
    });
    files.push(OutFile {
        path: "tsconfig.json".to_string(),
        contents: TSCONFIG.to_string(),
    });
    files.sort_by(|a, b| a.path.cmp(&b.path));
    Ok(files)
}

/// The compiled test files of a test build, sorted by path, relative to the project.
pub fn test_entries(files: &[OutFile]) -> Vec<String> {
    let mut list: Vec<String> = files
        .iter()
        .filter_map(|f| f.path.strip_suffix(".test.ts"))
        .map(|stem| format!("dist/{stem}.test.js"))
        .collect();
    list.sort();
    list
}

/// The command that runs the built program: the entry file under `dist/`.
pub fn entry_file(program: &Program, example: Option<&str>) -> String {
    match example {
        Some(name) => format!("dist/examples/{name}.js"),
        None => match program.kind {
            ProgramKind::Cli => "dist/src/main.js".to_string(),
            ProgramKind::Lib => "dist/src/lib.js".to_string(),
        },
    }
}

const TSCONFIG: &str = r#"{
  "compilerOptions": {
    "strict": true,
    "target": "ES2022",
    "lib": ["ES2022"],
    "module": "NodeNext",
    "moduleResolution": "NodeNext",
    "rootDir": ".",
    "outDir": "dist",
    "skipLibCheck": true
  },
  "include": ["src", "examples", "test"]
}
"#;

fn package_json(program: &Program) -> String {
    let exports = match program.kind {
        ProgramKind::Lib => "  \"exports\": \"./dist/src/lib.js\",\n",
        ProgramKind::Cli => "",
    };
    // `[extern.ts.dependencies]`, copied verbatim (spec chapter 8, section 2, rule 5).
    let dependencies = match program.dependencies.get("ts") {
        Some(list) if !list.is_empty() => {
            let entries: Vec<String> = list
                .iter()
                .map(|(name, version)| format!("    {}: {}", json(name), json(version)))
                .collect();
            format!("  \"dependencies\": {{\n{}\n  }},\n", entries.join(",\n"))
        }
        _ => String::new(),
    };
    format!(
        "{{\n  \"name\": \"{}\",\n  \"version\": \"{}\",\n  \"private\": true,\n  \"type\": \"module\",\n{exports}  \"scripts\": {{\n    \"build\": \"tsc\",\n    \"test\": \"tsc && node --test\"\n  }},\n{dependencies}  \"devDependencies\": {{\n    \"typescript\": \"^5.0.0\"\n  }}\n}}\n",
        program.name, program.version
    )
}

/// A JSON string.
fn json(text: &str) -> String {
    let mut out = String::from("\"");
    for c in text.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// The part of `node:test` that generated tests use (there are no Node.js type packages).
const NODE_TEST: &str = "// Generated by wolf. Do not edit.\n\ndeclare module \"node:test\" {\n  export function test(name: string, run: () => void): void;\n}\n";

/// A reporter for `node:test` that prints the report of `wolf test` (spec chapter 8, 2.7).
const REPORTER: &str = r#"// Prints the results of node:test in the format of `wolf test`.

export default async function* reporter(source) {
  let passed = 0;
  const failures = [];
  for await (const event of source) {
    const data = event.data ?? {};
    const name = typeof data.name === "string" ? data.name : "";
    const ours = name.includes(".wolf: ");
    if (event.type === "test:pass" && ours && !data.skip) {
      passed++;
      yield `test ${name} ... ok\n`;
    } else if (event.type === "test:fail") {
      const error = data.details?.error;
      const cause = error?.cause ?? error;
      const message = cause?.message ?? String(cause);
      if (ours || message !== "test failed") {
        // A failed test, or a test file that could not run at all.
        failures.push([name, message]);
        yield `test ${name} ... FAILED\n`;
      }
    }
  }
  if (failures.length > 0) {
    yield "\nfailures:\n";
    for (const [name, message] of failures) {
      yield `\n  ${name}\n    ${message}\n`;
    }
  }
  const result = failures.length > 0 ? "FAILED" : "ok";
  yield `\ntest result: ${result}. ${passed} passed; ${failures.length} failed\n`;
}
"#;
